/**
 * gen-api-routes.ts — route generator for the /api/v1 redesign (Phase 2).
 *
 * Walks `src/lib/server/api/defs/**\/*.ts` and emits +server.ts route files
 * for both surfaces:
 *
 *   src/routes/api/<path>/+server.ts       ← internal surface
 *   src/routes/api/v1/<path>/+server.ts    ← v1 token surface
 *
 * Each generated file is a thin mount:
 *
 *   import { mount } from '$lib/server/api/mount.js';
 *   import { def } from '$lib/server/api/defs/<path>.js';
 *   export const { GET, POST } = mount(def, { surface: 'v1' });
 *
 * The generated files carry an AUTO-GENERATED header and are checked in so
 * SvelteKit's file-system router sees them. Run `gen-api-routes --check` in CI
 * to verify generated files are up-to-date.
 *
 * Usage:
 *   npx tsx --tsconfig tsconfig.scripts.json scripts/gen-api-routes.ts
 *   npx tsx --tsconfig tsconfig.scripts.json scripts/gen-api-routes.ts --check
 *   npx tsx --tsconfig tsconfig.scripts.json scripts/gen-api-routes.ts --dry-run
 *
 * Convention (see src/lib/server/api/defs/_readme.ts for details):
 *   - defs/<path>.ts          → routes at api/<path>/ and api/v1/<path>/
 *   - defs/<path>/index.ts    → routes at api/<path>/ and api/v1/<path>/
 *   - Files prefixed with `_` (like _readme.ts) are skipped.
 */

import fs from 'node:fs';
import path from 'node:path';
import { glob } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..');
const defsRoot = path.join(repoRoot, 'src', 'lib', 'server', 'api', 'defs');
const routesRoot = path.join(repoRoot, 'src', 'routes');

// ---------------------------------------------------------------------------
// CLI flags
// ---------------------------------------------------------------------------

const CHECK_MODE = process.argv.includes('--check');
const DRY_RUN = process.argv.includes('--dry-run') || CHECK_MODE;

// ---------------------------------------------------------------------------
// Route surface definitions
// ---------------------------------------------------------------------------

interface RouteSurface {
    prefix: string; // URL prefix for this surface
    surface: string; // surface value passed to mount()
    routeDir: string; // absolute path to src/routes/api[/v1]
}

const SURFACES: RouteSurface[] = [
    {
        prefix: '/api',
        surface: 'internal',
        routeDir: path.join(routesRoot, 'api'),
    },
    {
        prefix: '/api/v1',
        surface: 'v1',
        routeDir: path.join(routesRoot, 'api', 'v1'),
    },
];

// ---------------------------------------------------------------------------
// File path → route path resolution
// ---------------------------------------------------------------------------

/**
 * Convert a def file path to a route-relative path (no leading slash).
 *
 *   defs/series/[id].ts        → 'series/[id]'
 *   defs/series/index.ts       → 'series'
 *   defs/media/[id]/similar.ts → 'media/[id]/similar'
 */
function defFileToRoutePath(defFile: string): string {
    // Make relative to defs root
    const rel = path.relative(defsRoot, defFile);
    // Strip .ts extension
    let routePath = rel.replace(/\.ts$/, '');
    // index.ts → parent directory
    if (path.basename(routePath) === 'index') {
        routePath = path.dirname(routePath);
        if (routePath === '.') routePath = '';
    }
    // Normalize path separators
    return routePath.split(path.sep).join('/');
}

// ---------------------------------------------------------------------------
// Code generation
// ---------------------------------------------------------------------------

// Marker string embedded in the generated header. The generator OWNS only the
// files that carry this marker (plus any target path that does not yet exist).
// Hand-written route files (no marker) are left untouched — neither rewritten
// in write-mode nor flagged in --check. See the idempotent-additive contract in
// src/lib/server/api/defs/_readme.ts.
const GENERATED_MARKER = 'AUTO-GENERATED by scripts/gen-api-routes.ts';

const GENERATED_HEADER = `// SPDX-FileCopyrightText: 2026 Denis Arnst (Sapd)
// SPDX-License-Identifier: AGPL-3.0-only
// ${GENERATED_MARKER} — DO NOT EDIT MANUALLY.
// Re-run the generator after modifying the def file.
`;

/**
 * Compute the relative import path from the generated route file to the def.
 *
 * The def file is in src/lib/server/api/defs/. The route file is in
 * src/routes/api[/v1]/<path>/+server.ts. SvelteKit aliases $lib → src/lib,
 * so we can always use a $lib import for the def (never a relative path).
 *
 * The generated route also imports from mount.ts via $lib/server/api/mount.js.
 */
function buildDefImportPath(routePath: string, defFile: string): string {
    // Use $lib-relative path (SvelteKit alias, always works)
    const defRel = path.relative(path.join(repoRoot, 'src', 'lib'), defFile);
    const defImport = '$lib/' + defRel.replace(/\.ts$/, '.js').split(path.sep).join('/');
    return defImport;
}

/**
 * Generate the content of a +server.ts route file for one surface.
 */
function generateRouteFile(routePath: string, defFile: string, surface: RouteSurface): string {
    const defImport = buildDefImportPath(routePath, defFile);
    const surfaceValue = surface.surface;

    return `${GENERATED_HEADER}
/**
 * ${surface.prefix}/${routePath}
 * Mounted from: ${defImport.replace('$lib/', 'src/lib/')}
 */

import { mount } from '$lib/server/api/mount.js';
import { def } from '${defImport}';

// Mount the endpoint definition onto the \${surfaceValue} surface.
// All method exports (GET/POST/PUT/PATCH/DELETE/OPTIONS/HEAD) are derived
// from the def's handlers map. Methods not in the def are not exported.
const { GET, POST, PUT, PATCH, DELETE, OPTIONS, HEAD } = mount(def, {
    surface: '${surfaceValue}',
});
export { GET, POST, PUT, PATCH, DELETE, OPTIONS, HEAD };
`;
}

// ---------------------------------------------------------------------------
// Main: discover, generate, write/check
// ---------------------------------------------------------------------------

interface GeneratedFile {
    targetPath: string;
    content: string;
}

/**
 * A defs/ file is a mountable ENDPOINT only when it exports `def`
 * (`export const def = …` or `export { def }`). Many files under defs/ are
 * supporting modules — schemas, strategy implementations, shared handlers,
 * helpers — that export named symbols but no `def`. Those must never be turned
 * into routes. We detect the `def` export with a cheap source scan.
 */
function exportsDef(file: string): boolean {
    let src: string;
    try {
        src = fs.readFileSync(file, 'utf8');
    } catch {
        return false;
    }
    // Strip comments so a documented `export const def = …` inside a JSDoc
    // example (e.g. defs/interactions/handlers.ts) is not mistaken for a real
    // export. Block comments first, then line comments.
    const code = src.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');
    // A MOUNTABLE endpoint file declares the def locally: `export const def = …`.
    // The `export { def as alias } from …` barrel re-export form (catalog/index.ts)
    // is intentionally NOT matched — those aliased defs are mounted by hand-written
    // routes, and the barrel itself is not a route.
    return /(^|\n)\s*export\s+const\s+def\b/.test(code);
}

/**
 * Explicit per-def opt-out. A def file may carry the directive
 *
 *   // gen-api-routes: skip
 *
 * to declare that it is NOT generator-mounted. Use this for defs that are
 * authored ahead of their route migration and are currently served by a
 * hand-written/legacy route at a path that differs from this generator's
 * filename convention (e.g. defs/catalog/series-id.ts, whose live route is the
 * bespoke /api/series/[id]). Without this, the generator would emit a route at
 * the convention path (/api/v1/catalog/series-id) that nothing consumes.
 *
 * This is an EXPLICIT, greppable signal — preferred over fragile path
 * heuristics. Remove the directive when the def is actually migrated to the
 * generator's convention path.
 */
function hasSkipDirective(file: string): boolean {
    let src: string;
    try {
        src = fs.readFileSync(file, 'utf8');
    } catch {
        return false;
    }
    return /\/\/\s*gen-api-routes:\s*skip\b/.test(src);
}

async function discoverDefs(): Promise<string[]> {
    if (!fs.existsSync(defsRoot)) {
        console.log('defs/ directory not found — nothing to generate');
        return [];
    }

    const pattern = path.join(defsRoot, '**', '*.ts');
    const files: string[] = [];
    for await (const f of glob(pattern)) {
        const base = path.basename(f);
        // Skip _-prefixed files (documentation, internal).
        if (base.startsWith('_')) continue;
        // Skip co-located test files (*.test.ts, *.spec.ts) — they are not defs.
        if (/\.(test|spec)\.ts$/.test(base)) continue;
        // Skip supporting modules that export no `def` (schemas, helpers,
        // strategies, etc.) — only files exporting an EndpointDef map to routes.
        if (!exportsDef(f)) continue;
        // Honor explicit opt-out (`// gen-api-routes: skip`) for defs authored
        // ahead of their route migration / served by a non-convention route.
        if (hasSkipDirective(f)) continue;
        files.push(f);
    }
    return files.sort();
}

/**
 * Scan every existing +server.ts route under src/routes/api/** for static
 * imports of defs (`from '$lib/server/api/defs/<X>.js'`). A def that is ALREADY
 * mounted by a hand-written route — frequently at a path that differs from this
 * generator's filename convention (e.g. defs/catalog/media-id.ts is hand-mounted
 * at routes/api/v1/media/[id]/) — must be left to that hand-written route. The
 * generator only manages defs that nothing already mounts by hand.
 *
 * Returns the set of def import specifiers found, normalized to the
 * `$lib/...` form WITHOUT the trailing `.js`, so it can be matched against
 * buildDefImportPath() output.
 */
async function discoverHandMountedDefs(): Promise<Set<string>> {
    const mounted = new Set<string>();
    const pattern = path.join(routesRoot, 'api', '**', '+server.ts');
    const importRe = /from\s+['"](\$lib\/server\/api\/defs\/[^'"]+)['"]/g;
    for await (const f of glob(pattern)) {
        // Files this generator owns are not "hand mounts".
        let src: string;
        try {
            src = fs.readFileSync(f, 'utf8');
        } catch {
            continue;
        }
        if (src.includes(GENERATED_MARKER)) continue;
        let m: RegExpExecArray | null;
        while ((m = importRe.exec(src)) !== null) {
            mounted.add(m[1].replace(/\.js$/, ''));
        }
    }
    return mounted;
}

async function main(): Promise<void> {
    const defFiles = await discoverDefs();

    if (defFiles.length === 0) {
        console.log('No endpoint def files found under src/lib/server/api/defs/');
        console.log(
            '(This is expected for the foundation layer — add def files to generate routes)',
        );
        process.exit(0);
    }

    // Locate the v1 surface — it is the migration "anchor" for a def (see the
    // per-def opt-in rule below).
    const v1Surface = SURFACES.find((s) => s.surface === 'v1');
    if (!v1Surface) throw new Error('v1 surface missing from SURFACES config');

    // Defs already mounted by hand-written routes (often at a non-convention
    // path) are owned by those routes, not the generator.
    const handMounted = await discoverHandMountedDefs();

    const toGenerate: GeneratedFile[] = [];
    let defsSkipped = 0;

    for (const defFile of defFiles) {
        const routePath = defFileToRoutePath(defFile);
        if (!routePath) {
            console.warn(`Skipping top-level defs file with no route path: ${defFile}`);
            continue;
        }

        // PER-DEF OPT-OUT (hand mounts): if any hand-written route already
        // imports this def, the generator must not also emit routes for it —
        // the hand mount is authoritative (and may live at a different path).
        const defImport = buildDefImportPath(routePath, defFile).replace(/\.js$/, '');
        if (handMounted.has(defImport)) {
            defsSkipped++;
            continue;
        }

        // PER-DEF OPT-IN (idempotent-additive contract; see defs/_readme.ts):
        //
        // A def's routes are generated as a PAIR (internal + v1). The v1 file is
        // the migration anchor: a def is "generator-managed" only once its v1
        // route file is generator-owned (carries the AUTO-GENERATED marker) OR
        // does not exist yet (a brand-new def being onboarded). If the v1 file
        // already exists and is HAND-WRITTEN (no marker), the def has NOT been
        // migrated to the generator — skip BOTH surfaces so we neither rewrite
        // the bespoke v1 file nor create a possibly-conflicting internal twin.
        //
        // This makes porting opt-in per def: extract the def, then either delete
        // its bespoke v1 file (the generator recreates a generator-owned twin) or
        // mark it generated. Until then, the def's existing surfaces are untouched
        // and --check stays green for un-migrated defs.
        const v1RouteDir = path.join(v1Surface.routeDir, ...routePath.split('/'));
        const v1TargetPath = path.join(v1RouteDir, '+server.ts');
        if (fs.existsSync(v1TargetPath)) {
            const v1Content = fs.readFileSync(v1TargetPath, 'utf8');
            if (!v1Content.includes(GENERATED_MARKER)) {
                defsSkipped++;
                continue;
            }
        }

        for (const surface of SURFACES) {
            const routeDir = path.join(surface.routeDir, ...routePath.split('/'));
            const targetPath = path.join(routeDir, '+server.ts');
            const content = generateRouteFile(routePath, defFile, surface);
            toGenerate.push({ targetPath, content });
        }
    }

    let changed = 0;
    let upToDate = 0;
    let skipped = 0;
    const errors: string[] = [];

    for (const { targetPath, content } of toGenerate) {
        const exists = fs.existsSync(targetPath);
        const currentContent = exists ? fs.readFileSync(targetPath, 'utf8') : null;

        // SECOND GUARD (per-file): even for a generator-managed def, never clobber
        // a hand-written file on EITHER surface (e.g. the internal SSE facade that
        // re-exports test helpers, which the template cannot reproduce). A file
        // that exists without the marker is hand-written — leave it alone: never
        // rewrite it in write-mode and never flag it in --check.
        if (exists && currentContent !== null && !currentContent.includes(GENERATED_MARKER)) {
            skipped++;
            continue;
        }

        if (currentContent === content) {
            upToDate++;
            continue;
        }

        changed++;

        if (CHECK_MODE) {
            const rel = path.relative(repoRoot, targetPath);
            errors.push(`OUT OF DATE: ${rel}`);
            continue;
        }

        if (!DRY_RUN) {
            fs.mkdirSync(path.dirname(targetPath), { recursive: true });
            fs.writeFileSync(targetPath, content, 'utf8');
            console.log(
                `  ${exists ? 'UPDATED' : 'CREATED'} ${path.relative(repoRoot, targetPath)}`,
            );
        } else {
            console.log(
                `  [dry-run] WOULD ${exists ? 'UPDATE' : 'CREATE'} ${path.relative(repoRoot, targetPath)}`,
            );
        }
    }

    console.log(`\ngen-api-routes: ${toGenerate.length} files processed`);
    console.log(`  up-to-date: ${upToDate}`);
    console.log(`  changed:    ${changed}`);
    console.log(`  skipped (hand-written, no marker): ${skipped}`);
    console.log(`  defs not yet migrated (bespoke v1 anchor): ${defsSkipped}`);

    if (CHECK_MODE && errors.length > 0) {
        console.error('\nCI check failed — generated route files are out of date:');
        for (const e of errors) console.error(`  ${e}`);
        console.error('\nRun: npx tsx --tsconfig tsconfig.scripts.json scripts/gen-api-routes.ts');
        process.exit(1);
    }

    if (!DRY_RUN && changed > 0) {
        console.log('\nGenerated route files updated. Run `npm run check:critical` to verify.');
    }
}

main().catch((err) => {
    console.error('gen-api-routes failed:', err);
    process.exit(1);
});
